  const same=sameLocalElection(snapshot.a?.meta,snapshot.b?.meta),indices=Object.fromEntries(['a','b'].map(s=>[s,new Map(collections[s].features.map(f=>[f.properties.id,f.properties]))]));
  for(const side of ['a','b'])for(const f of collections[side].features){const p=f.properties,a=indices.a.get(p.id),b=indices.b.get(p.id);p.a=side==='a'?p.votes:same?a?.votes??null:null;p.sa=side==='a'?p.share:same?a?.share??null:null;p.b=side==='b'?p.votes:same?b?.votes??null:null;p.sb=side==='b'?p.share:same?b?.share??null:null;p.point_comparable=same&&p.a!=null&&p.b!=null;p.delta=p.point_comparable&&p.sa!=null&&p.sb!=null?sem.sign*(p.sb-p.sa):null;p.dv=p.point_comparable?sem.sign*(p.b-p.a):null;}
  collections.d=same?{type:'FeatureCollection',features:collections.a.features.map(f=>({...f,properties:{...f.properties}}))}:{type:'FeatureCollection',features:[]};
  return collections;
