function initMaps(){document.querySelectorAll('.map-card[data-map]').forEach(el=>el.classList.toggle('mobile-active',el.dataset.map===activeMap));for(const side of ['a','b','d'])if(!maps[side]){const m=maps[side]=L.map(`map-${side}`,{scrollWheelZoom:false,preferCanvas:true}).setView([-22.9,-43.3],10);m.attributionControl.setPrefix('IPP · IBGE · fontes municipais');m.on('moveend',()=>{if(syncing||!m.getSize().x||!m.getSize().y||!Number.isFinite(m.getCenter().lat))return;syncing=true;for(const [s,other]of Object.entries(maps))if(s!==side)syncMapFrame(other,m.getCenter(),m.getZoom());syncing=false;});}}
