function resultGeometryKey(features,points,level,side){const meta=state[side==='d'?'a':side].data?.meta;return `${level}|${points.length?[meta?.year,meta?.date,meta?.turno,meta?.election_type].join(':'):''}|${matchMedia('(max-width:820px)').matches?'mobile':'desktop'}|${features.map(f=>String(f.properties.id)).join('|')}@${points.map(f=>`${f.properties.id}/${f.properties.territory_id}=${f.geometry.coordinates.join(',')}`).join('|')}`;}
