  message.textContent=level==='zona'&&side==='d'&&!sameLocalElection(state.a.data?.meta,state.b.data?.meta)?'Diferença por zona indisponível entre estas eleições: limites e composição ainda não verificados. Os resultados de cada eleição permanecem nos mapas dos candidatos.':!collection.features.length?'Nenhuma geometria disponível para esta seleção. Consulte os votos e o motivo na tabela.':'';
