async function preset(name){for(const s of ['a','b']){state[s].person=name==='Flávio Valle'?'flavio_valle':'paes';$(`year-${s}`).value=s==='a'?'2024':'2026';$(`turn-${s}`).value='1';}$('scope').value='capital';$('level').value='bairro';$('territory').value='';const completed=await Promise.all(['a','b'].map(s=>populateDataset(s,name==='Flávio Valle'?(s==='a'?'13':'7'):(s==='a'?'11':'3'),'60011')));if(completed.every(Boolean)){for(const side of ['a','b'])state[side].cityAppliedDataset=state[side].datasetRequest;await render();}}
async function selectCandidate(side,candidate){
  $(`year-${side}`).value=String(candidate.year);$(`turn-${side}`).value='1';
  state[side].person=null;
  const loading=populateDataset(side,candidate.cargo,candidate.ue),request=state[side].datasetRequest;
  if(!await loading||state[side].datasetRequest!==request)return false;
  const c=state[side].data?.candidates.find(c=>c.id===candidate.candidate);
  if(!c)throw Error('Candidatura indisponível nesta versão dos dados.');
  state[side].candidate=c.id;state[side].person=personId(c,state[side].data.meta)||norm(c.full_name);
  populateCandidates(side);if(!await loadCandidate(side,request))return false;
  if(candidate.cargo==='11')autoCity(side);
  state[side].cityAppliedDataset=state[side].datasetRequest;
  if(candidate.cargo==='13'){$('scope').value=candidate.ue==='60011'?'capital':'municipio';$('municipality').value=candidate.ue;$('level').value='bairro';$('territory').value='';}
  await render();
}
async function initRivals(){
  const rivals=[{year:2018,cargo:'3',ue:'RJ',name:'WILSON WITZEL'},{year:2022,cargo:'3',ue:'RJ',name:'CLÁUDIO CASTRO'},{year:2026,cargo:'3',ue:'RJ',name:'DOUGLAS RUAS'},{year:2024,cargo:'11',ue:'60011',name:'ALEXANDRE RAMAGEM'},{year:2020,cargo:'11',ue:'60011',name:'CRIVELLA'}];
  const candidacies=await Promise.all(rivals.map(async rival=>{
    const dataset=allDatasets.find(d=>d.year===rival.year&&d.cargo===rival.cargo&&d.turno==='1'&&d.ue===rival.ue);
    if(!dataset)return null;
    const data=await json(dataset.file),candidate=data.candidates.find(c=>norm(c.name)===norm(rival.name));
    return candidate?{...candidate,year:rival.year,cargo:rival.cargo,ue:rival.ue,candidate:candidate.id}:null;
  }));
  $('rivals-results').innerHTML=[3,2,4,0,1].map(i=>{const c=candidacies[i];return c?`<article class="card rival-candidate"><p class="rival-election">${c.cargo==='11'?'PREFEITO · RIO DE JANEIRO':'GOVERNADOR'} · ${c.year} · 1º TURNO</p><h3>${esc(c.name)}</h3><p class="rivals-note">${esc(c.party)} · Nº ${esc(c.number)} · ${fmt(c.votes)} votos ${c.cargo==='11'?'na capital':'no estado'}</p><div class="rival-actions"><button class="secondary" data-rival="${i}" data-rival-side="a" aria-label="Selecionar ${esc(c.name)} em ${c.year} como referência">Selecionar referência</button><button class="secondary" data-rival="${i}" data-rival-side="b" aria-label="Selecionar ${esc(c.name)} em ${c.year} como comparado">Selecionar comparado</button></div></article>`:'';}).join('');
  $('rivals-status').textContent=candidacies.some(c=>!c)?'Algumas candidaturas estão indisponíveis nesta versão dos dados.':'';
  $('rivals-results').addEventListener('click',async event=>{
    const button=event.target.closest('button[data-rival-side]');if(!button)return;
    const c=candidacies[Number(button.dataset.rival)],side=button.dataset.rivalSide;
    const buttons=$('rivals-results').querySelectorAll('button');buttons.forEach(b=>b.disabled=true);
    $('rivals-status').textContent=`Carregando ${c.name} · ${c.year}…`;
    try{await selectCandidate(side,c);$('rivals-status').textContent=`${c.name} · ${c.year} selecionado como ${side==='a'?'referência':'comparado'}.`;}
    catch(e){$('rivals-status').textContent=e.message;}
    finally{buttons.forEach(b=>b.disabled=false);}
  });
}
async function methodology(){
  const [sources,geo,audits,metro]=await Promise.all([json('sources.json'),json('geography-sources.json'),Promise.all(catalog.years.map(y=>json(`audit-${y.year}.json`).catch(()=>({year:y.year,status:'indisponivel'})))),json('metro_geography_sources.json').catch(()=>null)]);
  const electoral=Array.isArray(sources)?sources:Object.values(sources.resources||sources.sources||sources).filter(v=>v&&typeof v==='object');
  const rows=[...electoral,...geo.sources,...(metro?.sources||[])];
  const ma=metro?.audit;$('metro-methodology').innerHTML=ma?`<h2>Bairros metropolitanos e referência territorial</h2><p>${fmt(ma.bairros_validos)} bairros válidos em ${fmt(ma.municipios_com_bairros)} dos ${fmt(ma.municipios_escopo)} municípios metropolitanos. Petrópolis usa a proposta municipal de 45 bairros, identificada como referência cartográfica e não como lei de abairramento aprovada. Paracambi tem mapas dos locais de votação e agregação pelo bairro informado pelo TSE; a malha de bairros permanece pendente. A cobertura de votos é calculada por eleição e município, sem confundir área coberta com votos localizados.</p><p>Referência: ${esc(metro.territorial_reference)}. ${fmt(ma.quarentena)} geometrias ficaram em quarentena; há ${fmt(ma.overlap_pairs)} pares de polígonos com sobreposição. Pontos em mais de um bairro permanecem sem atribuição automática.</p><p>A vigência jurídica de algumas malhas permanece sem confirmação, incluindo Queimados em relação à Lei Complementar 100/2023. As classificações mostram a versão da fonte usada e as lacunas efetivas de votação.</p><a href="data/metro_geography_sources.json" download>Baixar manifesto metropolitano</a>`:'';
  const cases=geographicEvidence.capital_cases||geographicEvidence.cases||[];
  $('geographic-cases').innerHTML=`<h2>Evidências dos bairros sem seções associadas</h2><p>Os casos abaixo distinguem divergência de coordenadas, mudança de prédio, bairros recentes e inventário ainda em revisão. Ausência no cadastro não comprova ausência de eleitores residentes ou zero votos. A precisão dos endereços é conferida separadamente da conservação dos totais.</p><p><a href="data/geographic-evidence.json" download>Baixar evidências da capital</a> · <a href="data/petropolis-local-coverage.json" download>Baixar conferência independente dos locais de Petrópolis — cinco eleições</a></p><div class="evidence-list">${cases.map(row=>`<details><summary>${esc(row.bairro||row.bairro_id)} · ${esc(row.year??row.ano)} · ${esc(EVIDENCE_STATUS[row.status]||row.status)}</summary><p>${esc(row.evidencia||row.evidence||'')}</p><p><b>Procedimento / pendência:</b> ${esc(row.acao||row.action||'')}</p><p>${(row.fontes||[]).filter(url=>/^https?:\/\//.test(url)).map((url,index)=>`<a href="${esc(url)}" target="_blank" rel="noopener">Fonte ${index+1}</a>`).join(' · ')}</p></details>`).join('')}</div>`;
  renderGeographicAudits();
  const status={verified:'Conferida',verified_zip_crc:'CRC conferido',zip_crc_verified:'CRC conferido',parsed_json:'Estrutura conferida',complete:'Completo',verified_with_version_exclusions:'Conferida com diferenças de versão documentadas',divergences:'Divergências: recortes afetados bloqueados'};
  $('source-table').querySelector('tbody').innerHTML=rows.map(r=>`<tr><td>${esc(r.path||r.file||r.resource_name||r.id||'')}</td><td>${esc(r.generated_at||r.generation||'Não informada')}</td><td>${esc(r.collected_at?.slice(0,10)||'—')}</td><td>${esc(status[r.integrity]||r.integrity||'—')}<br><small>${fmt(r.size_bytes??r.bytes)} bytes</small></td><td><a href="${esc(r.source||r.url||'#')}" target="_blank" rel="noopener">Fonte oficial ↗</a>${r.legal_validity?`<br><small>${esc(r.legal_validity)}</small>`:''}<br><details><summary>SHA256</summary><code style="overflow-wrap:anywhere">${esc(r.sha256||'Não disponível')}</code></details></td></tr>`).join('');
  $('audit-content').innerHTML=`<div class="audit-cards">${audits.map(a=>{const extra=a.unmatched_section_contests||[],excluded=extra.filter(r=>r.excluded_from_current_valid).reduce((n,r)=>n+r.votes,0),unresolved=extra.filter(r=>!r.excluded_from_current_valid).reduce((n,r)=>n+r.votes,0);return `<article class="card audit-card"><strong>${a.year}</strong><p>${a.status==='processed'?'Processado':'Indisponível'}</p><p>Reconciliação: ${esc(status[a.nominal_reconciliation]||a.nominal_reconciliation||'—')}</p><p>Divergências de candidato/zona: ${fmt(a.divergent_candidate_zones)}</p><p>Votos de seção fora do nominal válido atual, com conferência exata: ${fmt(excluded)}</p><p>Votos de seção pendentes de conferência: ${fmt(unresolved)}</p><p>Locais em revisão geográfica: ${fmt(a.pending_geography)}</p><a href="data/audit-${a.year}.json" download>Baixar auditoria por zona</a></article>`;}).join('')}</div>`;
}
async function navigateView(view,updateHash=true){
  const name=view==='metodologia'?'metodologia':'comparar';
  document.querySelectorAll('.nav').forEach(el=>el.classList.toggle('active',el.dataset.view===name));
  document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===name));
  if(updateHash&&location.hash!==`#${name}`)location.hash=name;
  if(name==='metodologia')await methodology();else for(const map of Object.values(maps))map.invalidateSize({pan:false});
}
