for(const s of ['a','b']){$(`year-${s}`).replaceChildren(...catalog.years.map(y=>option(y.year,y.year,String(y.year)===(s==='a'?'2024':'2026'))));for(const f of ['year','turn'])$(`${f}-${s}`).addEventListener('change',async()=>{try{if(!await populateDataset(s,null,null,{preserveContest:f==='turn'}))return;autoCity(s);state[s].cityAppliedDataset=state[s].datasetRequest;await render();}catch(e){showError(e);}});$(`dataset-${s}`).addEventListener('change',async()=>{try{if(!await loadDataset(s))return;autoCity(s);state[s].cityAppliedDataset=state[s].datasetRequest;await render();}catch(e){showError(e);}});$(`search-${s}`).addEventListener('input',()=>populateCandidates(s));$(`candidate-${s}`).addEventListener('change',async()=>{if($(`candidate-${s}`).disabled)return;state[s].candidate=$(`candidate-${s}`).value||null;const c=selected(s);if(c)state[s].person=personId(c,state[s].data.meta)||norm(c.full_name);try{if(!await loadCandidate(s))return;if(state[s].cityAppliedDataset!==state[s].datasetRequest){autoCity(s);state[s].cityAppliedDataset=state[s].datasetRequest;}await render();}catch(e){showError(e);}});}
